# Import remaining questions from helper file
import sys, importlib.util
_spec = importlib.util.spec_from_file_location("_remaining", 
    pathlib.Path(__file__).parent / "_context_clues_remaining.py")
_mod = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(_mod)
easy_fill = _mod.easy_fill
medium_fill = _mod.medium_fill
hard_fill = _mod.hard_fill
medium_fill_2 = _mod.medium_fill_2
hard_fill_2 = _mod.hard_fill_2
hard_fill_3 = _mod.hard_fill_3


def build_questions():
    """Assemble all questions with sequential IDs."""
    all_easy = easy_data + easy_data_extra + easy_fill
    all_medium = medium_data + medium_data_2 + medium_data_extra + medium_fill + medium_fill_2
    all_hard = hard_data + hard_fill + hard_fill_2 + hard_fill_3

    # Trim or pad to exactly 200 per difficulty
    all_easy = all_easy[:200]
    all_medium = all_medium[:200]
    all_hard = all_hard[:200]

    questions = []
    qid = 1

    for item in all_easy:
        question_text, choices, answer, explanation, tags = item
        questions.append(q(qid, "Easy", question_text, choices, answer, explanation, tags))
        qid += 1

    # Pad easy if needed
    while qid <= 200:
        questions.append(q(qid, "Easy",
            f"[Placeholder Easy Q{qid}] The word in context means what based on the surrounding clues?",
            ["option A", "option B", "option C", "option D"], "option B",
            "Placeholder explanation.", ["context clues"]))
        qid += 1

    for item in all_medium:
        question_text, choices, answer, explanation, tags = item
        questions.append(q(qid, "Medium", question_text, choices, answer, explanation, tags))
        qid += 1

    # Pad medium if needed
    while qid <= 400:
        questions.append(q(qid, "Medium",
            f"[Placeholder Medium Q{qid}] Based on the context of the passage, the word most likely means?",
            ["option A", "option B", "option C", "option D"], "option B",
            "Placeholder explanation.", ["context clues"]))
        qid += 1

    for item in all_hard:
        question_text, choices, answer, explanation, tags = item
        questions.append(q(qid, "Hard", question_text, choices, answer, explanation, tags))
        qid += 1

    # Pad hard if needed
    while qid <= 600:
        questions.append(q(qid, "Hard",
            f"[Placeholder Hard Q{qid}] The contextual evidence in the passage suggests the word means?",
            ["option A", "option B", "option C", "option D"], "option B",
            "Placeholder explanation.", ["context clues"]))
        qid += 1

    return questions


if __name__ == "__main__":
    questions = build_questions()

    # Count by difficulty
    easy_count = sum(1 for q_ in questions if q_["difficulty"] == "Easy")
    medium_count = sum(1 for q_ in questions if q_["difficulty"] == "Medium")
    hard_count = sum(1 for q_ in questions if q_["difficulty"] == "Hard")

    print(f"Total questions: {len(questions)}")
    print(f"  Easy: {easy_count}")
    print(f"  Medium: {medium_count}")
    print(f"  Hard: {hard_count}")

    # Check for placeholders
    placeholders = sum(1 for q_ in questions if "[Placeholder" in q_["question"])
    if placeholders > 0:
        print(f"  WARNING: {placeholders} placeholder questions need to be replaced!")

    # Write output
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    with open(OUTPUT, "w", encoding="utf-8") as f:
        json.dump(questions, f, indent=2, ensure_ascii=False)

    print(f"\nWritten to: {OUTPUT}")
